#@title 1 · Elige tu perfil y registra decisiones (modifica los valores)
PERFIL_IMAGEN = "grises" #@param ["grises","contraste","bordes"]
LADO_IMAGEN = 320 #@param [160,320,640] {type:"raw"}
GANANCIA_AUDIO = 1.0 #@param [0.5,1.0,1.5] {type:"raw"}
POSICION_VOZ = 1 #@param {type:"integer"}
ALTERNATIVA_DESCARTADA = 0 #@param [0,1,2,3] {type:"raw"}
LIMITE_ELEGIDO = 0 #@param [0,1,2,3] {type:"raw"}
# Alternativa: 1 = imagen sin reducción, 2 = audio sin conservar RAW, 3 = guardar solo CSV.
# Límite: 1 = RMS no transcribe, 2 = histograma no reconoce objetos, 3 = coincidencia de metadatos no prueba causalidad.
assert PERFIL_IMAGEN in ("grises","contraste","bordes")
assert LADO_IMAGEN in (160,320,640) and GANANCIA_AUDIO in (0.5,1.0,1.5)
assert type(POSICION_VOZ) is int and 1 <= POSICION_VOZ <= 10
assert ALTERNATIVA_DESCARTADA in (0,1,2,3) and LIMITE_ELEGIDO in (0,1,2,3)
DECISIONES = {"perfil_imagen":PERFIL_IMAGEN,"lado_imagen":LADO_IMAGEN,
 "ganancia_audio":GANANCIA_AUDIO,"voz_elegida":POSICION_VOZ,
 "alternativa_descartada":ALTERNATIVA_DESCARTADA,"limite_elegido":LIMITE_ELEGIDO}
print("DECISIONES ESTRUCTURADAS:",DECISIONES)

#@title 8H · Importar el ZIP del E2E web al mismo cuaderno (opcional)
IMPORTAR_ZIP_WEB=False #@param {type:"boolean"}
if IMPORTAR_ZIP_WEB:
    puente_web=cargar_modulo_s11("s10_asset_bridge")
    if EN_COLAB:
        from google.colab import files as archivos_colab
        subidos=archivos_colab.upload()
        if len(subidos)!=1:raise ValueError("Selecciona un ZIP únicamente")
        nombre,contenido=next(iter(subidos.items()))
        if not nombre.lower().endswith(".zip"):raise ValueError("Se espera ZIP")
        ruta_zip=RAIZ/"etl_usuario.zip"
        ruta_zip.write_bytes(contenido)
    else:
        ruta_zip=RAIZ/"etl_usuario.zip"
        if not ruta_zip.is_file():
            raise FileNotFoundError(f"Copia tu ZIP del navegador aquí: {ruta_zip}")
    importe_web=puente_web.importar_zip_etl_web(ruta_zip,RAIZ)
    filas_web=pd.read_json(importe_web["catalogo"],lines=True)
    assert importe_web["cantidad"]==len(filas_web)
    assert filas_web["source_kind"].isin(["uploaded_by_student","generated_for_course"]).all()
    print(importe_web["verificacion"],importe_web["cantidad"],"activos; sin relaciones editoriales ficticias")
    display(filas_web[["asset_id","modality","source_kind","profile","metric_name","metric_value"]])
else:
    print("El expediente oficial S11 sigue íntegro; puedes probar E2E en la presentación.")

#@title 9A · Generar un paquete ZIP real sin subir datos privados
ARCHIVO_FINAL=core.empaquetar(RAIZ)
print("SHA-256 ZIP:",core.sha256(ARCHIVO_FINAL))
DESCARGAR_ZIP=False #@param {type:"boolean"}
if DESCARGAR_ZIP:
    if EN_COLAB:
        from google.colab import files as archivos_colab
        archivos_colab.download(str(ARCHIVO_FINAL))
    else:
        print("En VS Code encontrarás el ZIP en:",ARCHIVO_FINAL)
else:
    print("ZIP disponible en el panel de archivos:",ARCHIVO_FINAL)
